<?php declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\Shared\{Db,RuntimeSchema};use Kulturhus\Native\Pos\{Register,Schema};use Kulturhus\Native\Payments\RefundPending;use Kulturhus\Verein\{Database,Finance};
$db=\Kulturhus\Native\TestSupport::db();Database::migrate($db);Schema::install($db);RuntimeSchema::install($db);$db->exec("INSERT INTO clubs VALUES('refund-club','Synthetic');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('cashier','refund-club','member',1)");$event=bin2hex(random_bytes(16));Db::run($db,'INSERT INTO event_voucher_events(club_id,id,source_id,title,starts_at,location) VALUES(?,?,?,?,?,?)',['refund-club',$event,'synthetic-refund','Synthetic refund event','2026-10-08T18:00:00Z','Saal']);$register=new Register($db,'cashier');$account=(new Finance($db,'cashier'))->createAccount('Synthetic cash','cash','0','2026-01-01');$shift=$register->open($event,$account,0);$gift=$register->saveProduct(['label'=>'Synthetic gift','price'=>'20.00','kind'=>'value-voucher','sphere'=>'wirtschaftlich']);$sale=$register->cart($shift,[['id'=>$gift,'quantity'=>1]],0,bin2hex(random_bytes(16)));$sale=$register->tender($sale['id'],$sale['version'],0);$attempt=$register->attempt($sale['id'],'paypal');$register->start($attempt['id'],fn()=>['external_id'=>'ORDER123']);$proof=['provider'=>'paypal','transaction_id'=>'CAPTURE123','reference'=>$attempt['reference'],'amount_cents'=>2000,'currency'=>'EUR','merchant'=>'SYNTHETICMERCH'];$sale=$register->verify($attempt['id'],fn()=>$proof);$original=$register->receipt($sale['id']);$n=0;function check(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);$n++;echo "PASS $label\n";}function denied(callable $f,string $label):void{try{$f();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$calls=0;$state=$register->refund($sale['id'],'Synthetic full refund',function()use(&$calls){$calls++;throw new RefundPending(['provider'=>'paypal','external_id'=>'REFUND123','transaction_id'=>'CAPTURE123']);});check($state['state']==='uncertain'&&$calls===1,'uncertain accepted refund persists once');check(json_decode($register->refundStatus($sale['id'])['result_json'],true)['external_id']==='REFUND123','provider checkpoint survives transaction rollback');check($register->sale($sale['id'])['state']==='paid','unverified refund never changes paid sale');$voucher=Db::run($db,'SELECT * FROM pos_value_vouchers WHERE club_id=? AND issued_sale=?',['refund-club',$sale['id']])->fetch();check($voucher['state']==='refund-pending'&&(int)$voucher['remaining_cents']===2000,'purchased gift is frozen before provider refund and cannot be spent meanwhile');denied(fn()=>$register->refund($sale['id'],'Repeat'),'uncertain refund cannot initiate another POST');denied(fn()=>$register->close($shift,0),'uncertain refund blocks shift ledger closure');
$readerCalls=0;$reader=function($payment,$id,$checkpoint)use(&$readerCalls,$proof){$readerCalls++;check($checkpoint['external_id']==='REFUND123','read-only recovery receives exact provider checkpoint');return $proof+['confirmed'=>true,'external_id'=>'REFUND123'];};$db->exec("UPDATE actors SET active=0 WHERE id='cashier'");denied(fn()=>$register->reconcileRefund($sale['id'],$reader),'revoked cashier cannot reconcile');check($readerCalls===0,'revoked cashier makes no provider read');$db->exec("UPDATE actors SET active=1 WHERE id='cashier'");denied(fn()=>$register->reconcileRefund($sale['id'],fn()=>array_replace($proof,['confirmed'=>true,'external_id'=>'OTHER','amount_cents'=>1])),'changed refund amount cannot settle');$r=$register->reconcileRefund($sale['id'],$reader);check($r['state']==='confirmed'&&$register->sale($sale['id'])['state']==='refunded','independent matching proof finishes durable refund');check(Db::run($db,'SELECT state FROM pos_value_vouchers WHERE club_id=? AND id=?',['refund-club',$voucher['id']])->fetchColumn()==='refunded','confirmed refund permanently revokes purchased gift');check($register->receipt($sale['id'])===$original,'refund retains immutable original receipt');check($register->reconcileRefund($sale['id'],$reader)['state']==='confirmed'&&$readerCalls===1,'completed recovery never restores or refunds twice');check($register->close($shift,0)['state']==='closed','confirmed refund permits exact cash closure');echo "$n native refund recovery checks passed; isolated synthetic MySQL, no provider requests.\n";
